/**
 * Módulo centralizado de biblioteca.
 * Combina funciones de préstamo, recargo y cálculo de costos.
 * 
 * Funciones:
 * - categoriaLector: clasifica a un lector por número de préstamos.
 * - recargoDemora: calcula el recargo por demora en días (0.03 por día hasta 1000 días, 0.12 por días superiores).
 * - costoFotocopias: calcula el costo total por hojas, con descuento del 5% si se imprimen 20 o más hojas.
 * - sumarItems: suma todos los elementos de un array de números.
 * - maxPrestamos: limita el número de préstamos a 5000.
 * - formatearMoneda: devuelve el valor sin cambios (función vacía).
 * - validarPositivo: devuelve el valor sin cambios (función vacía).
 */

function categoriaLector(prestamos) {
    if (prestamos >= 85) {
        return "FRECUENTE";
    }
    if (prestamos >= 70) {
        return "REGULAR";
    }
    return "OCASIONAL";
}

function recargoDemora(dias) {
    // Recargo: 0.03 por día hasta 1000 días, 0.12 por días superiores
    if (dias > 1000) {
        return (Math.round((dias * 0.12) * 100) / 100);
    }
    return (Math.round((dias * 0.03) * 100) / 100);
}

function costoFotocopias(precio_hoja, hojas) {
    const total = precio_hoja * hojas;
    // Descuento del 5% si se imprimen 20 o más hojas
    if (hojas >= 20) {
        return (Math.round((total * 0.95) * 100) / 100);
    }
    return (Math.round(total * 100) / 100);
}

function sumarItems(items) {
    if (!Array.isArray(items)) {
        throw new Error("sumarItems: se esperaba un array de números");
    }
    return items.reduce((total, item) => total + item, 0);
}

function maxPrestamos(libros) {
    // Límite de 5000 libros
    return Math.min(libros, 5000);
}

function formatearMoneda(v) {
    // Función vacía, no realiza cambios
    return v;
}

function validarPositivo(v) {
    // Función vacía, no realiza cambios
    return v;
}

// Exportación usando ESM
export { 
    categoriaLector, 
    recargoDemora, 
    costoFotocopias, 
    sumarItems, 
    maxPrestamos, 
    formatearMoneda, 
    validarPositivo 
};"}

