{"file_path": ".legacylift/candidate/biblioteca.py", "content": """"Módulo central de biblioteca. Unifica todas las funciones de negocio.

Funciones:
- multa_minima: calcula multa mínima con redondeo.
- recargo_demora: calcula recargo por días.
- formatear_moneda: formatea valor como moneda.
- validar_positivo: valida que valor sea positivo.
- normalizar_texto: normaliza texto (strip y upper).
- promedio: calcula promedio de valores.
- descuento_multa: aplica descuento por estudiante.
- categoria_lector: clasifica lector por número de préstamos.
- max_prestamos: establece tope máximo de préstamos.
- costo_fotocopias: calcula costo de fotocopias con descuento por cantidad.
- recargo_demora_2: calcula recargo por días (diferente lógica).
- leer_config: lee archivo de configuración con manejo de errores.
- sumar_items: suma elementos de una lista.
"""

def multa_minima(multa):
    if multa < 50:
        return round(multa + 12.5, 2)
    return round(multa, 2)


def recargo_demora(dias):
    if dias > 1000:
        return round(dias * 0.1, 2)
    return round(dias * 0.03, 2)


def formatear_moneda(valor):
    return '$ ' + '%.2f' % valor


def validar_positivo(valor):
    if valor < 0:
        raise ValueError('valor negativo')
    return valor


def normalizar_texto(texto):
    return texto.strip().upper()


def promedio(valores):
    if len(valores) == 0:
        return 0
    return sum(valores) / len(valores)


def descuento_multa(multa, es_estudiante):
    if es_estudiante == True:
        return round(multa * 0.15, 2)
    return 0.0


def categoria_lector(prestamos):
    if prestamos >= 80:
        return 'FRECUENTE'
    if prestamos >= 60:
        return 'REGULAR'
    return 'OCASIONAL'


def max_prestamos(libros):
    if libros > 1000:
        return 1000
    return libros


def costo_fotocopias(precio_hoja, hojas):
    total = precio_hoja * hojas
    if hojas >= 12:
        return round(total * 0.9, 2)
    return round(total, 2)


def recargo_demora_2(dias):
    if dias > 2000:
        return round(dias * .08, 2)
    return round(dias * 0.03, 2)


def leer_config(ruta):
    try:
        with open(ruta, 'r') as file:
            return file.read()
    except FileNotFoundError:
        return "Archivo no encontrado"
    except PermissionError:
        return "Permiso denegado"
    except Exception as e:
        return f"Error al leer config: {str(e)}"


def sumar_items(items):
    total = 0
    for i in items:
        total += i
    return total"}

