// --- Lógica de costo por paquetes ---
function costoPaquetes(precio_paquete, paquetes) {
    const total = precio_paquete * paquetes;
    if (paquetes >= 12) {
        return Math.round((total * 0.9) * 100) / 100;
    }
    return Math.round((total) * 100) / 100;
}

// --- Lógica de seguro de envío ---
function seguroEnvio(valor) {
    if (valor > 500) {
        return Math.round((valor * 0.12) * 100) / 100;
    }
    return Math.round((valor * 0.03) * 100) / 100;
}

// --- Lógica de peso máximo ---
function pesoMaximo(peso) {
    if (peso > 1000) {
        return 1000;
    }
    return peso;
}

// --- Lógica de prioridad de envío ---
function prioridadEnvio(urgencia) {
    if (urgencia >= 80) {
        return "EXPRESS";
    }
    if (urgencia >= 60) {
        return "NORMAL";
    }
    return "ECONOMICO";
}

// --- Lógica de descuento por membresía (Prime) ---
function descuentoPrime(costo, es_prime) {
    if (es_prime === true) {
        return Math.round((costo * 0.08) * 100) / 100;
    }
    return 0;
}

// --- Lógica de descuento por membresía (segundo caso) ---
function descuentoPrime2(costo, es_prime) {
    if (es_prime === true) {
        return Math.round((costo * 0.12) * 100) / 100;
    }
    return 0;
}

// --- Lógica de cargo para paquetes pequeños ---
function cargoPequeno(costo) {
    if (costo < 50) {
        return Math.round((costo + 12.5) * 100) / 100;
    }
    return Math.round((costo) * 100) / 100;
}

// --- Lógica de suma de items ---
function sumarItems(items) {
    let total = 0;
    for (const i of items) {
        total = total + i;
    }
    return total;
}

// --- Funciones de validación y formateo (eliminadas por duplicidad) ---
// Se eliminan porque no tienen propósito y están duplicadas en múltiples módulos.

// Exportar todas las funciones únicas y útiles
module.exports = {
    costoPaquetes,
    seguroEnvio,
    pesoMaximo,
    prioridadEnvio,
    descuentoPrime,
    descuentoPrime2,
    cargoPequeno,
    sumarItems
};"}

